SITUACAO_MATRIZPPC_APROVADA = '5'


def vincular_matriz_de_pafcs_elaborados(apps, schema_editor):
    """
    Ajusta cadastro de PAFCs cuja tramitação iniciou antes do suporte a múltiplas matrizes.
    Mesmo se tratando de PAFCs de matriz única, é preciso ajustar os registros porque a estrutura de classes mudou.
    Para isso, esta atualização vai buscar os PAFCs cujo PPC associado possua apenas uma matriz e criá-la automaticamente.
    O processamento vai desconsiderar PAFCs em estágio inicial ou que já tenham sido finalizados.
    """
    PAFC = apps.get_model("pafc", "PAFC")
    MatrizPAFC = apps.get_model("pafc", "MatrizPAFC")

    pafcs_elaborados = PAFC.objects.filter(matrizpafc__isnull=True, situacao__in=SITUACAO_POS_ELABORACAO)
    novas_vinculacoes_de_matriz = []
    for pafc in pafcs_elaborados:
        qs_matrizppc = pafc.ppc.matrizppc_set
        if not qs_matrizppc.exclude(situacao_matriz=SITUACAO_MATRIZPPC_APROVADA).exists():
            matrizes = list(qs_matrizppc.all())
            if len(matrizes) == 1:
                novas_vinculacoes_de_matriz.append(
                    MatrizPAFC(pafc=pafc, matriz_ppc=matrizes[0])
                )
    MatrizPAFC.objects.bulk_create(novas_vinculacoes_de_matriz)


